refentry.refsect1:
&reftitle.description;
arrayarray_pad arrayarray intlength mixedvalue
array_pad ले length द्वारा तोकिएको size सम्म value value ले pad गरिएको array को एउटा copy return गर्दछ। यदि length positive छ भने array दायाँतर्फ pad गरिन्छ, यदि यो negative छ भने बायाँतर्फ। यदि length को absolute value, array को length भन्दा कम वा बराबर छ भने कुनै पनि padding हुँदैन।

&reftitle.changelog;







     &Version;
     &Description;





     8.3.0
     8.3 भन्दा पहिले, एक पटकमा 1048576 elements मात्र थप्न सकिन्थ्यो। अब यसको सट्टा यो एउटा array को अधिकतम size द्वारा मात्र सीमित गरिएको छ।

  &reftitle.examples;



    array_pad को उदाहरण


<?php
$input = array(12, 10, 9);

$result = array_pad($input, 5, 0);
// result is array(12, 10, 9, 0, 0)
echo join(', ', $result), PHP_EOL;

$result = array_pad($input, -7, -1);
// result is array(-1, -1, -1, -1, 12, 10, 9)
echo join(', ', $result), PHP_EOL;

$result = array_pad($input, 2, "noop");
// not padded
echo join(', ', $result), PHP_EOL;
?>
